    ko: { title: "\ud638\uc8fc \uc0dd\ud65c FAQ \u2014 \ube44\uc790, \uc740\ud589, \uc138\uae08, \uc77c\uc790\ub9ac", description: "\ud638\uc8fc \uc0dd\ud65c\uc5d0 \ub300\ud55c \uc790\uc8fc \ubb3b\ub294 \uc9c8\ubb38 \u2014 \ube44\uc790, \uc740\ud589, \uc138\uae08, \uc77c\uc790\ub9ac, \ub80c\ud2b8, \uc758\ub8cc \ub4f1. \uc0c8\ub85c \uc628 \uc0ac\ub78c\uacfc \uc720\ud559\uc0dd, \uc6cc\ud640\ub7ec\ub97c \uc704\ud55c \uc2e4\uc6a9\uc801\uc778 \ub2f5\ubcc0." },
