    ko: { title: "\ud638\uc8fc \uc740\ud589\u00b7\uc138\uae08 \uac00\uc774\ub4dc \u2014 TFN, \uc288\ud37c, \uc138\uae08 \uc2e0\uace0", description: "\uc740\ud589 \uacc4\uc88c \uac1c\uc124, TFN \uc2e0\uccad, \uc288\ud37c \uc218\ub839, \uc138\uae08 \uc2e0\uace0 \u2014 \ud638\uc8fc\uc5d0 \uc0c8\ub85c \uc628 \uc0ac\ub78c\uc744 \uc704\ud55c \ub3c8\uacfc \uc740\ud589\uc758 \ud544\uc218 \uc815\ubcf4." },
