    ja: { title: "\u30aa\u30fc\u30b9\u30c8\u30e9\u30ea\u30a2\u51fa\u767a\u524d \u2014 4\u301c6\u9031\u9593\u306e\u6e96\u5099\uff1a\u30d3\u30b6\u30fb\u9280\u884c\u30fb\u8377\u9020\u308a", description: "\u30aa\u30fc\u30b9\u30c8\u30e9\u30ea\u30a2\u3078\u306e\u5f15\u3063\u8d8a\u3057\u6e96\u5099 \u2014 4\u301c6\u9031\u9593\u306e\u30c1\u30a7\u30c3\u30af\u30ea\u30b9\u30c8\u3002\u30d3\u30b6\u3001\u9280\u884c\u3001\u304a\u91d1\u3001\u30b9\u30de\u30db\u3001\u30a2\u30d7\u30ea\u3001\u8377\u9020\u308a\u3001\u4f4f\u307e\u3044\u3001\u533b\u7642\u4fdd\u967a\u3001\u7a7a\u6e2f\u307e\u3067\u306e\u4ea4\u901a\u3002\u5230\u7740\u524d\u306b\u5fc5\u8981\u306a\u3059\u3079\u3066\u3002" },
