    ko: { title: "\ud638\uc8fc \uc815\ucc29 3\ub2e8\uacc4 \u2014 \ub3c4\ucc29 \uc804, \uccab \ub2ec, \uc7a5\uae30 \uc815\ucc29", description: "\ub3c4\ucc29 \uc804, \ub9c9 \ub3c4\ucc29\ud55c \uc2dc\uae30, \uc7a5\uae30 \uc815\ucc29\uae4c\uc9c0 \uc138 \ub2e8\uacc4\ub85c \ubcf4\ub294 \ud638\uc8fc \uc5ec\uc815. \ube44\uc790, \uc740\ud589, SIM, TFN, \uc9d1 \uad6c\ud558\uae30, \uc601\uc8fc\uad8c, \uce5c\uad6c \ub9cc\ub4e4\uae30." },
