/** The page's own title and description for a locale, falling back to English. */
export function pageMeta(route: string, locale: Lang): PageMeta {
  const entry = PAGE_META[route];
  if (!entry) throw new Error(`pageMeta: no metadata for ${route}`);
  return entry[locale] ?? entry.en;
}
